.fc-sim-container.mi .mi-table th { color: var(--mi-ink-3); font-weight: 650; background: #faf7f2; }
.fc-sim-container.mi .mi-table th:first-child, .fc-sim-container.mi .mi-table td:first-child { text-align: left; }
