            for (var i = 0; i < h.length; i++) { prof += h[i].profit; lost += h[i].lostStock + h[i].lostTime; }
            var solvent = ds.minCash >= FCModel.M.CUSHION;
            var k = function (label, val) { return '<div class="mi-dkpi"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var html = '<div class="mi-debrief-head">'
                + '<p class="mi-kicker">' + this._t('d_kicker') + '</p>'
                + '<h2 class="mi-h2" id="miDebriefTitle">' + this._t('d_title') + '</h2>'
                + '<p class="mi-debrief-score"><strong>' + s + '</strong><small>/100</small><span class="mi-chip mi-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + '<p class="mi-debrief-sub">' + this._t('d_sub', { o: perf.outcome, p: perf.process }) + '</p></div>'
                + '<div class="mi-dkpis">'
                + k(this._t('d_k_cash'), this._usd(last.cash)) + k(this._t('d_k_profit'), this._signed(prof))
                + k(this._t('d_k_served'), this._num(ds.served)) + k(this._t('d_k_lost'), this._num(lost))
                + k(this._t('d_k_inv'), this._num(last.inv)) + k(this._t('d_k_story'), Math.round(100 * ds.story) + '/100') + '</div>'
                + '<p class="mi-rule ' + (solvent ? 'is-ok' : 'is-no') + '">' + (solvent ? '✓ ' : '✗ ') + this._t(solvent ? 'd_rule_ok' : 'd_rule_no', { c: this._usd(ds.minCash) }) + '</p>'
                + (perf.cap === 'cash' ? '<p class="mi-notice">' + this._t('cap_cash') + '</p>' : '')
                + '<h3>' + this._t('d_turning') + '</h3><p class="mi-turning">' + a.turning + '</p>'
                + '<h3>' + this._t('d_insights') + '</h3><ul class="mi-insights">' + a.insights.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>'
                + '<h3>' + this._t('d_questions') + '</h3><ol class="mi-questions">' + a.questions.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ol>';
            return html;
        }

        /* ---------- painting ---------- */
        _runOver(st) {
            try { if (window.mySimulation && typeof window.mySimulation.isRunComplete === 'function') { return !!window.mySimulation.isRunComplete(); } } catch (e) {}
            var maxP = (st && st.maxPeriods) || FC_MONTHS;
            if (st && st.currentPeriod > maxP) { return true; }
            var h = (st && st.history) || (window.mySimulation && window.mySimulation.history) || [];
            return h.length >= maxP;
        }

        _bind() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            FC_IDS.forEach(function (id) {
                var el = document.getElementById(id);
                if (!el) { return; }
                var h = function () { try { self._paintOutputs(); self._paintPreview(); var v = self._el('miValidation'); if (v) { v.textContent = ''; } } catch (e) {} };
                el.addEventListener('input', h);
                el.addEventListener('change', h);
            });
            document.addEventListener('express:langchanged', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                f.eventBus.on('language:changed', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
                f.eventBus.on('period:submitted', function () { try { self._render(); } catch (e) {} });
                f.eventBus.on('period:undone', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('state:loaded', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('simulation:complete', function () { try { self._render(); } catch (e) {} });
            }
        }

        /* On resume or undo, the controls show the player's own last decisions, not the authored defaults. */
        _syncControls() {
            var st = this._state();
            if (!st) { return; }
            var d = st.decisions || {};
            var put = function (id, v) { var el = document.getElementById(id); if (el && v !== undefined && v !== null && v !== '' && isFinite(Number(v))) { el.value = String(v); } };
            put('productionInput', d.production);
            put('priceInput', d.price);
            put('digitalInput', d.digital);
            put('fairsInput', d.fairs);
            var hs = document.getElementById('helpInput');
            if (hs && d.help && FCModel.HELP.hasOwnProperty(d.help) && st.history && st.history.length) { hs.value = d.help; }
            this._paintOutputs();
        }

        _render() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState;
            var over = this._runOver(st);
            var m = over ? (st.history ? st.history.length : FC_MONTHS) : (st.currentPeriod || 1);
            this._paintStatic();
            this._paintSteps(m, over);
            this._paintBriefing(m, over);
            this._paintKpis(ds);
            this._paintScore(ds);
            this._paintResult(ds);
            this._paintOutputs();
            this._paintPreview();
            this._paintChartAlt(ds);
            var form = this._el('miForm'), deb = this._el('debriefPanel');
            if (over) {
                if (form) { form.hidden = true; }
                if (deb) { deb.innerHTML = this._debriefHTML(ds, this.getPerformanceSummary(st.history)); deb.hidden = false; }
            } else {
                if (form) { form.hidden = false; }
                if (deb) { deb.hidden = true; deb.innerHTML = ''; }
            }
            try { document.documentElement.lang = this._lang(); } catch (e) {}
        }

        _paintStatic() {
            var terms = ['margin', 'breakeven', 'cashprofit', 'stock', 'lost', 'capacity', 'cac', 'story', 'cushion'];
            var html = '';
            for (var i = 0; i < terms.length; i++) { html += '<dt>' + this._t('g_' + terms[i]) + '</dt><dd>' + this._t('g_' + terms[i] + '_d') + '</dd>'; }
            this._set('miGlossary', html);
            this._set('priceMin', this._usd(18));
            this._set('priceMid', this._usd(29));
            this._set('priceMax', this._usd(40));
            this._set('digitalMin', this._usd(0));
            this._set('digitalMid', this._usd(400));
            this._set('digitalMax', this._usd(800));
        }

        _paintSteps(m, over) {
            var html = '';
            for (var i = 1; i <= FC_MONTHS; i++) {
                var cls = (i < m || (over && i <= m)) ? 'is-done' : (i === m ? 'is-now' : '');
                html += '<li class="' + cls + '"><span>' + this._t('mon_short_' + i) + '</span></li>';
            }
            this._set('miSteps', html);
            var c = this._el('miCal');
            if (c) { c.textContent = over ? this._t('run_complete') : this._mon(m) + ' 2026'; }
        }

        _paintBriefing(m, over) {
            this._set('miTag', over ? this._t('tag_done') : this._t('tag_' + m));
            this._set('miBriefTitle', over ? this._t('brief_done_title') : this._t('brief_title_' + m));
            this._set('briefingText', over ? this._t('brief_done') : this._t('brief_' + m));
            this._set('miExample', over ? '' : this._t('example_' + m));
            var ex = this._el('miExample'); if (ex) { ex.hidden = over; }
        }

        _delta(cur, prev, fmt) {
            if (prev == null) { return ''; }
            var d = cur - prev, cls = d > 0 ? 'is-up' : (d < 0 ? 'is-down' : 'is-flat');
            return '<span class="mi-delta ' + cls + '">' + (d > 0 ? '▲ +' : d < 0 ? '▼ −' : '') + fmt(Math.abs(d)) + '</span> ' + this._t('vs_prev');
        }

        _paintKpis(ds) {
            var self = this, h = ds.hist || [], last = h[h.length - 1], prev = h[h.length - 2];
            if (!last) {
                this._set('cashDisplay', this._usd(ds.cash));
                this._set('cashSub', this._t('cash_start'));
                this._set('servedDisplay', '0');
                this._set('servedSub', this._t('served_start'));
                this._set('stockDisplay', this._num(ds.inv));
                this._set('stockSub', this._t('stock_start'));
                this._set('timeDisplay', '—');
                this._set('timeSub', this._t('time_start'));
                return;
            }
            this._set('cashDisplay', this._usd(last.cash));
            var cd = this._el('cashDisplay'); if (cd) { cd.className = 'mi-kpi-value' + (last.cash < FCModel.M.CUSHION ? ' is-bad' : ''); }
            this._set('cashSub', this._delta(last.cash, prev ? prev.cash : FCModel.M.CASH0, function (v) { return self._usd(v); }) + ' · ' + this._t('cash_cushion', { c: this._usd(FCModel.M.CUSHION) }));
            this._set('servedDisplay', this._num(ds.served));
            this._set('servedSub', this._t('served_sub', { n: last.sold, l: last.lostStock + last.lostTime }));
            this._set('stockDisplay', this._num(last.inv));
            this._set('stockSub', this._t('stock_sub', { v: this._usd(last.inv * FCModel.M.UNIT) }));
            this._set('timeDisplay', this._pct(Math.min(100, 100 * last.util)));
            var td = this._el('timeDisplay'); if (td) { td.className = 'mi-kpi-value' + (last.lostTime > 0 ? ' is-bad' : ''); }
            this._set('timeSub', this._t('time_sub', { n: Math.min(last.cap, Math.min(last.demand, last.avail)), c: last.cap, l: last.lostTime }));
        }

        _paintScore(ds) {
            var h = ds.hist || [], last = h[h.length - 1], p = ds.performance || {};
            if (!last) {
                this._set('miScoreCard', '<p class="mi-score-head">' + this._t('score_title') + '</p><p class="mi-score-empty">' + this._t('score_empty') + '</p>');
                return;
            }
            var tier = p.tier || 'lesson';
            var bar = function (label, v, cls) {
                var pct = Math.round(100 * (v || 0));
                return '<div class="mi-bar"><span>' + label + '</span><span class="mi-bar-track"><span class="mi-bar-fill ' + cls + '" style="width:' + pct + '%"></span></span><span class="mi-bar-val">' + pct + '</span></div>';
            };
            var html = '<p class="mi-score-head">' + this._t('score_title')
                + '<span class="mi-score-num">' + p.overallScore + '<small>/100</small></span>'
                + '<span class="mi-chip mi-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + bar(this._t('bar_cash'), p.cash, 'is-cash') + bar(this._t('bar_served'), p.served, 'is-served')
                + bar(this._t('bar_process'), (p.process || 0) / 100, 'is-process')
                + '<p class="mi-score-note">' + this._t('score_note') + '</p>'
                + (p.cap === 'cash' ? '<p class="mi-score-cap">' + this._t('cap_cash') + '</p>' : '');
            this._set('miScoreCard', html);
        }

        _paintResult(ds) {
            var h = ds.hist || [], r = h[h.length - 1];
            if (!r) {
                this._set('miResultPanel', '<h3 class="mi-h3">' + this._t('res_title_0') + '</h3><p class="mi-result-head">' + this._t('res_empty') + '</p>');
                return;
            }
            var li = [];
            li.push(this._t('res_sales', { d: r.demand, s: r.sold, p: this._usd(r.price), v: this._usd(r.revenue) }));
            if (r.lostStock > 0) { li.push('<strong>' + this._t('res_lost_stock', { n: r.lostStock, a: r.avail }) + '</strong>'); }
            if (r.lostTime > 0) { li.push('<strong>' + this._t('res_lost_time', { n: r.lostTime, c: r.cap }) + '</strong>'); }
            if (r.left > 0) { li.push(this._t('res_left', { n: r.left, s: r.shrink, i: r.inv })); }
            li.push(this._t('res_where', { f: r.fbuyers, d: r.dbuyers, o: Math.max(0, r.demand - r.fbuyers - r.dbuyers) }));
            if (r.m === 1) {
                var est = Math.round(r.demand / (ds.draw || 1));
                li.push(this._t(ds.draw > 1.01 ? 'res_signal_up' : (ds.draw < 0.99 ? 'res_signal_down' : 'res_signal_same'), { e: est, x: this._pct(Math.abs(100 * (ds.draw - 1))) }));
            }
            li.push(this._t(r.storyGain >= 0 ? 'res_story_up' : 'res_story_down', { s: Math.round(100 * r.story) }));
            li.push(this._t('res_cash', { p: this._signed(r.profit), c: this._usd(r.costs), cash: this._usd(r.cash) }));
            this._set('miResultPanel', '<h3 class="mi-h3">' + this._t('res_title', { m: this._monlc(r.m) }) + '</h3><ul class="mi-why">' + li.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>');
        }

        _paintOutputs() {
            var r = this._read();
            if (isFinite(r.production)) { this._set('productionOut', this._t('out_totes', { n: this._num(r.production) })); }
            if (isFinite(r.price)) { this._set('priceOut', this._usd(r.price)); }
            if (isFinite(r.digital)) { this._set('digitalOut', this._usd(r.digital)); }
            if (isFinite(r.fairs)) { this._set('fairsOut', this._t('out_fairs', { n: r.fairs, c: this._usd(r.fairs * FCModel.M.FAIR_COST) })); }
        }

        _paintPreview() {
            var st = this._state();
            if (!st || !st.domainState || this._runOver(st)) { this._set('miPreview', ''); return; }
            var ds = st.domainState, m = st.currentPeriod || 1, r = this._read();
            if (!isFinite(r.production) || !isFinite(r.price)) { return; }
            var d = FCModel.norm(r);
            var fc = FCModel.forecast(ds, d, m);
            var k = FCModel.helpers(r.help);
            var cap = FCModel.capacity(d.fairs, d.digital, k);
            var need = FCModel.outlay(d);
            var avail = ds.inv + d.production;
            var item = function (label, val, warn) { return '<div class="mi-prev-item' + (warn ? ' is-warn' : '') + '"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var dem = m <= 1 ? this._t('prev_range', { a: fc.lo, b: fc.hi }) : this._t('prev_about', { a: fc.mid });
            var html = item(this._t('prev_demand'), dem)
                + item(this._t('prev_avail'), this._t('prev_avail_v', { n: avail, i: ds.inv }), avail < fc.lo || avail > 1.6 * fc.mid)
                + item(this._t('prev_cap'), this._num(cap) + (r.help ? '' : ' ' + this._t('prev_cap_alone')), cap < fc.mid)
                + item(this._t('prev_pay'), this._usd(need), need > ds.cash)
                + item(this._t('prev_cash'), this._usd(ds.cash - need), ds.cash - need < FCModel.M.CUSHION);
            this._set('miPreview', html);
        }

        _paintChartAlt(ds) {
            var h = ds.hist || [];
            if (!h.length) { this._set('cashChartAlt', this._t('alt_empty')); this._set('ordersChartAlt', this._t('alt_empty')); return; }
            var l = h[h.length - 1], prof = 0, sold = 0, ls = 0, lt = 0;
            for (var i = 0; i < h.length; i++) { prof += h[i].profit; sold += h[i].sold; ls += h[i].lostStock; lt += h[i].lostTime; }
            var u = this._t(h.length === 1 ? 'unit_month' : 'unit_months');
            this._set('cashChartAlt', this._t('alt_cash', { a: this._usd(FCModel.M.CASH0), b: this._usd(l.cash), p: this._signed(prof), n: h.length, u: u }));
            this._set('ordersChartAlt', this._t('alt_orders', { s: sold, a: ls, b: lt, n: h.length, u: u }));
        }

        _paintCharts() {
            try {
                var f = window.mySimulation;
                if (f && f.uiManager && typeof f.uiManager.updateCharts === 'function') { f.uiManager.updateCharts(f.state); }
            } catch (e) {}
        }

